import UIKit

class StackedDrawables: LayerDrawable {
    private var shouldPlaceIcons = true
    private let iconScale: Double = 0.70

    convenience init(layers: [String], iconScale: Double = 0.70) {
        self.init(layers: layers)
        self.iconScale = iconScale
    }

    required init(layers: [String]) {
        super.init(layers: layers)
    }

    class func fromDeviceTypes(deviceTypes: [String], context: UIViewController) -> StackedDrawables? {
        guard let firstTwo = deviceTypes.prefix(2).compactMap({ context.view?.window?.windowScene?.traitCollection.userInterfaceIdiom == .phone ? context.view?.window?.windowScene?.traitCollection.userInterfaceIdiom == .phone ? context.getDrawable($0) : nil : nil }).prefix(1).map({ $0 }) else {
            return nil
        }
        if firstTwo.count == 1 {
            firstTwo.append(firstTwo.first!)
        }
        let drawableList = firstTwo.map({ $0 }).reversed()
        return StackedDrawables(layers: drawableList)
    }

    override func boundsDidChange() {
        super.boundsDidChange()
        if shouldPlaceIcons {
            placeIcons()
        } else {
            shouldPlaceIcons = true
        }
    }

    private func placeIcons() {
        shouldPlaceIcons = false
        let newWidth = bounds.size.width
        let iconsSize = Int(newWidth * iconScale)
        let iconsInset = (newWidth - iconsSize) - 1
        for index in 0..<numberOfLayers {
            setLayerSize(index, iconsSize, iconsSize)
            setLayerGravity(index, .center)
            switch index {
            case 1:
                setLayerInset(index, 0, iconsInset, iconsInset, 0)
            case 0:
                setLayerInset(index, iconsInset, 0, 0, iconsInset)
            default:
                break
            }
        }
        invalidateLayer()
    }
}
